import React, { useContext ,useState} from "react";
import PasswordContext from "../store/password-context";
import UserForm from "./UserForm";
import Modal from "../UI/Modal";
const SavedPassword = () => {
  const usePassword = useContext(PasswordContext);
  const [editingItem, setEditingItem] = useState(null);

  const editItem = (item) => {
      setEditingItem(item); // Set the item being edited
      // Remove the item from the screen
      const updatedItems = usePassword.item.filter((i) => i.id !== item.id);
      usePassword.addItem(updatedItems);
  };

  const deleteHandler = (itemId) => {
    usePassword.removeItem(itemId);
  };

  const editItemHandler = (itemId) => {
   
  };

  return (
    <div>
      {usePassword.openProduct && (
        <ul>
               <h4>All Passwords details :</h4>
          {usePassword.item.map((item) => (
            <li key={item.id} style={{ display: "flex" }}>
            
              <p>Title: {item.title} </p>
             
              <p style={{ marginLeft: "10px",marginRight:"10px" }}> Password :{item.password}</p>

              <button
                style={{ cursor: "pointer" ,height:"25px",width:"80px",alignSelf: "center"}}
                onClick={() => deleteHandler(item.id)}
              >
                Delete
              </button>
              <button
                style={{ cursor: "pointer" ,height:"25px",width:"80px",alignSelf: "center"}}
                onClick={() => editItemHandler(item.id)}
              >
                Edit
              </button>
            </li>
          ))}
        </ul>

      )}
        {editingItem && (
                <Modal>
                    <UserForm onEditItem={editItem}
                      editingItem={editingItem} /> 
                </Modal>
            )}
    </div>
  );
};
export default SavedPassword;
